API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Edge_Termination_Component, "Edge Termination Component", "AWS API Gateway with TLS 1.3", "Manages secure edge routing, TLS 1.3 termination, and latency-based multi-region routing via Route 53.")
    Component(Security_WAF_Component, "Security & WAF Component", "AWS WAF", "Provides OWASP Top-10 mitigation and edge security for incoming global traffic.")
    Component(Authentication_Authorization_Component, "Authentication & Authorization Component", "JWT/OAuth2 Validator", "Validates JSON Web Tokens and OAuth2 credentials for incoming buyer, reviewer, administrator, and support requests.")
}

Container(Cart_Checkout_Container, "Cart & Checkout Container", "Amazon ECS/EKS", "Handles cart and checkout operations.")

Rel(Security_WAF_Component, Edge_Termination_Component, "Filters and inspects incoming traffic")
Rel(Edge_Termination_Component, Authentication_Authorization_Component, "Passes terminated requests for credential validation")
Rel(Authentication_Authorization_Component, Cart_Checkout_Container, "Routes validated traffic", "mTLS")

@enduml

Localization & Compliance Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Localization & Compliance Container container

Container_Boundary(localization_compliance_container, "Localization & Compliance Container") {
    Component(Localization_Controller, "Localization Controller", "AWS ECS/EKS REST API Endpoint", "Routes regional localization and compliance requests, handling currency conversion and geo-lookup data.")
    Component(Compliance_Manager, "Compliance Manager", "AWS ECS/EKS Service Worker", "Ensures strict adherence to GDPR, CCPA, and multi-currency requirements across international markets.")
    Component(Data_Purge_Publisher, "Data Purge Publisher", "AWS SQS Client", "Publishes asynchronous GDPR/CCPA deletion requests securely.")
}

Rel(Localization_Controller, Compliance_Manager, "Validates and processes regional compliance and localization requests", "mTLS inside AWS VPC")
Rel(Compliance_Manager, Data_Purge_Publisher, "Sends asynchronous GDPR/CCPA deletion requests", "Encrypted TLS / AWS KMS")

@enduml

AWS ElastiCache.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_elasticache, "AWS ElastiCache") {
    Component(Catalog_Caching_Component, "Catalog Caching Component", "Redis Cluster Mode Enabled", "Retrieves and serves cached catalog data for low-latency page loads.")
    Component(Recommendation_Namespace_Component, "Recommendation Namespace Component", "Redis Namespace", "Maintains isolated recommendation data for the personalization engine.")
    Component(Cart_Namespace_Component, "Cart Namespace Component", "Redis Namespace", "Maintains isolated session and cart namespaces for active users.")
}

Rel(Catalog_Caching_Component, Recommendation_Namespace_Component, "Isolates cache data using Redis namespaces", "")
Rel(Catalog_Caching_Component, Cart_Namespace_Component, "Isolates cache data using Redis namespaces", "")
@enduml

Amazon SQS.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon SQS container

Container_Boundary(amazon_sqs, "Amazon SQS") {
    Component(Queue_Management_Interface, "Queue Management Interface", "AWS SDK with TLS 1.3", "Handles asynchronous fulfillment event queuing and message ingestion with 14-day maximum retention.")
    Component(Dead_Letter_Queue_Handler, "Dead-Letter Queue Handler", "AWS SQS DLQ", "Manages failed message routing and business continuity for unprocessable fulfillment events.")
    Component(Encryption_Service, "Encryption Service", "AWS KMS", "Provides Server-Side Encryption (SSE) using customer-managed keys for queue data protection.")
}

Rel(Queue_Management_Interface, Dead_Letter_Queue_Handler, "Routes failed messages upon processing exhaustion")
Rel(Queue_Management_Interface, Encryption_Service, "Encrypts and decrypts queue payloads using customer-managed keys")

@enduml
